  const int q0 = blockIdx.x * kBr;

  const int64_t bh  = (int64_t)b * H + h;
  const int64_t off = bh * (int64_t)S * D;

  // CuTe global-memory tensors for this (batch, head): (S, D) row-major
  Tensor mQ = make_tensor(make_gmem_ptr(Q + off),
      make_layout(make_shape(S, D), make_stride(D, Int<1>{})));
  Tensor mK = make_tensor(make_gmem_ptr(K + off),
      make_layout(make_shape(S, D), make_stride(D, Int<1>{})));
  Tensor mV = make_tensor(make_gmem_ptr(V + off),
      make_layout(make_shape(S, D), make_stride(D, Int<1>{})));
  Tensor mO = make_tensor(make_gmem_ptr(O + off),
      make_layout(make_shape(S, D), make_stride(D, Int<1>{})));

  const int tid  = threadIdx.x;
  const int row  = tid >> 4;   // query row inside the tile [0, kBr)
  const int lane = tid & 15;   // key index in score phase / column group in PV phase

  // ---- Load Q tile into shared memory (zero-pad out-of-range rows) ----
  for (int idx = tid; idx < kBr * D; idx += kThreads) {
    const int r = idx / D;
    const int c = idx - r * D;
    const int gr = q0 + r;
    sQ(r, c) = (gr < S) ? mQ(gr, c) : __float2half(0.0f);
  }
  __syncthreads();

  // ---- Output accumulators: thread owns O(row, c*16 + lane) ----
  float acc[kCPT];
  #pragma unroll
  for (int c = 0; c < kCPT; ++c) acc[c] = 0.0f;

  const int nc_raw = (D - lane + 15) >> 4;
  const int nc = nc_raw < kCPT ? (nc_raw > 0 ? nc_raw : 0) : kCPT;

  float m_run = -INFINITY;   // running row max
  float l_run = 0.0f;        // running row sum of exp

  const int kv_tiles = (S + kBc - 1) / kBc;

  for (int kt = 0; kt < kv_tiles; ++kt) {
    const int k0 = kt * kBc;

    // ---- Load K tile ----
    for (int idx = tid; idx < kBc * D; idx += kThreads) {
      const int r = idx / D;
      const int c = idx - r * D;
      const int gr = k0 + r;
      sKV(r, c) = (gr < S) ? mK(gr, c) : __float2half(0.0f);
    }
    __syncthreads();

    // ---- Scores: each thread computes one dot product (row, lane) ----
    float dot = 0.0f;
    #pragma unroll 8
    for (int d = 0; d < D; ++d) {
      dot += __half2float(sQ(row, d)) * __half2float(sKV(lane, d));
    }

    const int gk = k0 + lane;
    float score = (gk < S) ? dot * scale : -1e30f;  // mask invalid keys

    // Row max across the 16 keys of this row (16-lane warp segment)
    float tmax = score;
    #pragma unroll
    for (int o = 8; o > 0; o >>= 1) {
      tmax = fmaxf(tmax, __shfl_xor_sync(0xffffffffu, tmax, o, 16));
    }

    const float m_new = fmaxf(m_run, tmax);
    const float alpha = __expf(m_run - m_new);   // rescale factor for old partials
    const float p     = __expf(score - m_new);

    sP(row, lane) = p;

    // Row sum of p across the 16 keys
    float rowsum = p;
    #pragma unroll
    for (int o = 8; o > 0; o >>= 1) {
      rowsum += __shfl_xor_sync(0xffffffffu, rowsum, o, 16);
    }

    // Rescale old partial output
    #pragma unroll
    for (int c = 0; c < kCPT; ++c) acc[c] *= alpha;

    // ---- Load V tile (K buffer is free now) ----
    for (int idx = tid; idx < kBc * D; idx += kThreads) {
      const int r = idx / D;
      const int c = idx - r * D;
      const int gr = k0 + r;
      sKV(r, c) = (gr < S) ? mV(gr, c) : __float2half(0.0f);
    }
    __syncthreads();

    // ---- P @ V accumulate ----
    for (int j = 0; j < kBc; ++j) {
      const float pij = sP(row, j);
      #pragma unroll 8
      for (int c = 0; c < nc; ++c) {
        acc[c] += pij * __half2float(sKV(j, (c << 4) + lane));
      }
    }

    m_run = m_new;
    l_run = l_run * alpha + rowsum;

    __syncthreads();  // sKV is reused by the next tile
  }

  // ---- Epilogue: normalize and store ----
  const int gr = q0 + row;
  if (gr < S) {
    const float inv_l = 1.0f / l_run;
    for (int c = 0; c < nc; ++c) {
      mO(gr, (c << 4) + lane) = __float2half(acc[c] * inv_l);
    }
  }
}

}  // namespace

torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
  TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(),
              "Q, K, V must be CUDA tensors");
  TORCH_CHECK(Q.scalar_type() == at::kHalf &&
              K.scalar_type() == at::kHalf &&
              V.scalar_type() == at::kHalf,
              "Q, K, V must be float16");
  TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4,
              "Q, K, V must be 4D [B, H, S, D]");

  const int B = (int)Q.size(0);
  const int H = (int)Q.size(1);
  const int S = (int)Q.size(2);
  const int D = (int)Q.size(3);

  TORCH_CHECK(K.size(0) == B && K.size(1) == H && K.size(2) == S && K.size(3) == D,
              "K shape must match Q shape");
  TORCH_CHECK(V.size(0) == B && V.size(1) == H && V.size(2) == S && V.size(3) == D,
              "V shape must match Q shape");
  TORCH_CHECK(D >= 1 && D <= 16 * kCPT, "Head dimension D must be in [1, 1024]");

  auto q = Q.contiguous();
  auto k = K.contiguous();
  auto v = V.contiguous();
  auto out = torch::empty_like(q);

  const int Dpad = D + 2;
  const int smem_bytes =
      (kBr + kBc) * Dpad * (int)sizeof(__half) +
      kBr * kBc * (int)sizeof(float);

  static int max_smem = -1;
  if (max_smem < 0) {
    int dev = 0;
    cudaGetDevice(&dev);
    cudaDeviceGetAttribute(&max_smem, cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
  }
  TORCH_CHECK(smem_bytes <= max_smem,
              "Required dynamic shared memory exceeds device limit");

  if (smem_bytes > 48 * 1024) {
    auto attr_err = cudaFuncSetAttribute(
        (const void*)sdpa_fwd_kernel,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        smem_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
                "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));
  }

  const float scale = (float)(1.0 / std::sqrt((double)D));

  dim3 grid((unsigned)((S + kBr - 1) / kBr), (unsigned)H, (unsigned)B);
  dim3 block(kThreads);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  sdpa_fwd_kernel<<<grid, block, smem_bytes, stream>>>(
      reinterpret_cast<const __half*>(q.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(k.data_ptr<at::Half>()),
      reinterpret_cast<const __half*>(v.data_ptr<at::Half>()),
      reinterpret_cast<__half*>(out.data_ptr<at::Half>()),
      H, S, D, scale);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "sdpa_fwd_kernel launch failed: ", cudaGetErrorString(err));

  return out;
}
